tweaks.applyScript:
$Patterns = "App.StepsRecorder*","Browser.InternetExplorer*","Media.WindowsMediaPlayer*"
$Capabilities = Get-WindowsCapability -Online | Where-Object -FilterScript { $_.State -eq "Installed" }
foreach ($Pattern in $Patterns) { $Capabilities | Where-Object -FilterScript { $_.Name -like $Pattern } | Remove-WindowsCapability -Online -ErrorAction SilentlyContinue }

tweaks.revertScript:
$Patterns = "App.StepsRecorder*","Browser.InternetExplorer*","Media.WindowsMediaPlayer*"
$Capabilities = Get-WindowsCapability -Online | Where-Object -FilterScript { $_.State -eq "NotPresent" }
foreach ($Pattern in $Patterns) { $Capabilities | Where-Object -FilterScript { $_.Name -like $Pattern } | Add-WindowsCapability -Online -ErrorAction SilentlyContinue }

tweaks.applyScript:
if (Get-Package -Name "Microsoft Edge" -ErrorAction SilentlyContinue) {
 New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\EdgeUpdate" -Force -ErrorAction SilentlyContinue | Out-Null
 New-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\EdgeUpdate" -Name "CreateDesktopShortcut{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}" -PropertyType DWord -Value 0 -Force | Out-Null
}

$AdapterDACType = Get-CimInstance -ClassName CIM_VideoController | Where-Object -FilterScript { ($_.AdapterDACType -ne "Internal") -and ($null -ne $_.AdapterDACType) }
$ComputerSystemModel = (Get-CimInstance -ClassName CIM_ComputerSystem).Model -notmatch "Virtual"
$WddmVersion_Min = [Microsoft.Win32.Registry]::GetValue("HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\FeatureSetUsage", "WddmVersion_Min", $null)
if ($AdapterDACType -and $ComputerSystemModel -and ($WddmVersion_Min -ge 2700)) {
 New-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -Name HwSchMode -PropertyType DWord -Value 2 -Force | Out-Null
}

$VirtualizationFirmwareEnabled = (Get-CimInstance -ClassName CIM_Processor).VirtualizationFirmwareEnabled
if ($VirtualizationFirmwareEnabled) {
 Enable-WindowsOptionalFeature -FeatureName Containers-DisposableClientVM -All -Online -NoRestart -ErrorAction SilentlyContinue
} elseif ((Get-CimInstance -ClassName CIM_ComputerSystem).HypervisorPresent) {
 Enable-WindowsOptionalFeature -FeatureName Containers-DisposableClientVM -All -Online -NoRestart -ErrorAction SilentlyContinue
}

tweaks.revertScript:
$VirtualizationFirmwareEnabled = (Get-CimInstance -ClassName CIM_Processor).VirtualizationFirmwareEnabled
if ($VirtualizationFirmwareEnabled) {
 Disable-WindowsOptionalFeature -FeatureName Containers-DisposableClientVM -Online -NoRestart -ErrorAction SilentlyContinue
} elseif ((Get-CimInstance -ClassName CIM_ComputerSystem).HypervisorPresent) {
 Disable-WindowsOptionalFeature -FeatureName Containers-DisposableClientVM -Online -NoRestart -ErrorAction SilentlyContinue
}

$Adapters = Get-NetAdapter -Physical | Where-Object -FilterScript { $_.Status -eq "Up" }
$InterfaceGuids = @($Adapters.InterfaceGuid)
$Adapters | Get-NetIPInterface -AddressFamily IPv4 | Set-DnsClientServerAddress -ResetServerAddresses
foreach ($InterfaceGuid in $InterfaceGuids) {
 Remove-Item -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$InterfaceGuid\DohInterfaceSettings\Doh" -Recurse -Force -ErrorAction SilentlyContinue
}
Clear-DnsClientCache

